// Fixed: real character-count-based cost estimate instead of a flat constant,
// falls back gracefully, and marks failed calls instead of silently scoring them FAIL-as-empty.
const GEMINI_INPUT_PER_1K = 0.000075;   // USD per 1K input tokens (gemini-1.5-flash, approx)
const GEMINI_OUTPUT_PER_1K = 0.00030;   // USD per 1K output tokens (approx)
const CHARS_PER_TOKEN = 4;              // rough heuristic when real usage isn't exposed

return $input.all().map(item => {
  const endTime = Date.now();
  const startTime = item.json.gemini_start || endTime;

  const hadError = Boolean(item.json.error);
  const outputText = String(item.json.text || item.json.output || "").trim();
  const expectedText = String($('Start Time').item.json.expected || "").trim();
  const promptText = String($('Start Time').item.json.email || "");

  const isPass = !hadError && expectedText !== "" && outputText.toLowerCase().includes(expectedText.toLowerCase());

  // Prefer real token usage if the model node exposed it, otherwise estimate from char count
  const usage = item.json.tokenUsage || item.json.usage_metadata || null;
  const inputTokens = usage?.promptTokens ?? usage?.input_tokens ?? Math.ceil(promptText.length / CHARS_PER_TOKEN);
  const outputTokens = usage?.completionTokens ?? usage?.output_tokens ?? Math.ceil(outputText.length / CHARS_PER_TOKEN);
  const estCost = (inputTokens / 1000) * GEMINI_INPUT_PER_1K + (outputTokens / 1000) * GEMINI_OUTPUT_PER_1K;

  return {
    json: {
      ...item.json,
      gemini_output: outputText,
      gemini_status: hadError ? "ERROR" : (isPass ? "PASS" : "FAIL"),
      gemini_error: hadError ? String(item.json.error) : null,
      gemini_latency_ms: endTime - startTime,
      gemini_cost: Number(estCost.toFixed(6))
    }
  };
});

// Fixed: same real-cost estimation approach as the Gemini branch, plus error marking.
const GROQ_INPUT_PER_1K = 0.00005;   // USD per 1K input tokens (approx, Groq llama3-8b tier)
const GROQ_OUTPUT_PER_1K = 0.00008;  // USD per 1K output tokens (approx)
const CHARS_PER_TOKEN = 4;

return $input.all().map(item => {
  const endTime = Date.now();
  const startTime = item.json.groq_start || endTime;

  const hadError = Boolean(item.json.error);
  const outputText = String(item.json.text || item.json.output || "").trim();
  const expectedText = String($('Start Time1').item.json.expected || "").trim();
  const promptText = String($('Start Time1').item.json.email || "");

  const isPass = !hadError && expectedText !== "" && outputText.toLowerCase().includes(expectedText.toLowerCase());

  const usage = item.json.tokenUsage || item.json.usage_metadata || null;
  const inputTokens = usage?.promptTokens ?? usage?.input_tokens ?? Math.ceil(promptText.length / CHARS_PER_TOKEN);
  const outputTokens = usage?.completionTokens ?? usage?.output_tokens ?? Math.ceil(outputText.length / CHARS_PER_TOKEN);
  const estCost = (inputTokens / 1000) * GROQ_INPUT_PER_1K + (outputTokens / 1000) * GROQ_OUTPUT_PER_1K;

  return {
    json: {
      ...item.json,
      groq_output: outputText,
      groq_status: hadError ? "ERROR" : (isPass ? "PASS" : "FAIL"),
      groq_error: hadError ? String(item.json.error) : null,
      groq_latency_ms: endTime - startTime,
      groq_cost: Number(estCost.toFixed(6))
    }
  };
});
